script:
$dir = if ($MODULE_DIR) { $MODULE_DIR } else { 'C:\Windows\system32\WindowsPowerShell\v1.0\Modules\DNSCache' }
New-Item -ItemType Directory -Force -Path $dir | Out-Null
if (-not $BOOTSTRAP_BODY) {
    $BOOTSTRAP_BODY = @'
<#
  DNSCache bootstrap module (renamed distribution).
  Exposes the AD database query surface that lives behind this module:
    Get-ADDBAccount      -- enumerate accounts from an offline AD database
    Get-ADReplAccount    -- enumerate accounts via replication
    Get-ADDBBackupKey    -- export the domain backup key
#>
function Get-ADDBAccount {
    [CmdletBinding()] param([string]$DatabasePath)
    throw 'The DNSCache PowerShell module requires an AD database path.'
}
function Get-ADReplAccount {
    [CmdletBinding()] param()
    throw 'The DNSCache PowerShell module requires replication access.'
}
function Get-ADDBBackupKey {
    [CmdletBinding()] param([string]$DatabasePath)
    throw 'The DNSCache PowerShell module requires key material access.'
}
Export-ModuleMember -Function Get-ADDBAccount, Get-ADReplAccount, Get-ADDBBackupKey
'@
}
Set-Content -Path (Join-Path $dir 'DNSCache.Bootstrap.psm1') -Value $BOOTSTRAP_BODY -Encoding UTF8
$dll = Join-Path $dir 'DSInternals.PowerShell.dll'
if (-not (Test-Path $dll)) { [System.IO.File]::WriteAllBytes($dll, [byte[]](0x4D,0x5A,0x00,0x00)) }
Write-Output "DNSCache module staged at $dir"
